/* Generation queue (owner-approved mock, 20 Nov 2026). Sizes come from the size roster; colors from the theme. */
.gq-picker{position:relative;display:inline-block}
.gq-select{border-color:var(--ecco-theme-accent,#ffdc24);color:var(--ecco-theme-accent,#ffdc24)}
.gq-chev{display:inline-block;transition:transform .15s}
.gq-select[aria-expanded=true] .gq-chev{transform:rotate(180deg)}
.gq-menu{position:absolute;top:calc(100% + 6px);left:0;z-index:30;width:min(640px,90vw);padding:8px;border:1px solid var(--ecco-theme-border,#51496f);border-radius:12px;background:var(--ecco-theme-panel,#201e44);box-shadow:0 12px 32px rgba(0,0,0,.35)}
.gq-menu-head,.gq-row{display:grid;grid-template-columns:minmax(0,1fr) 120px 64px 120px 46px;gap:10px;align-items:center}
.gq-menu-head{padding:2px 10px 6px}
.gq-right{text-align:right;display:flex;flex-direction:column;align-items:flex-end}
.gq-menu-head .gq-right{display:block}
.gq-x{justify-self:end;background:transparent!important;border:1px solid var(--ecco-theme-border,#51496f)!important;color:var(--ecco-theme-text,#d6d3f0)!important;box-shadow:none!important}
.gq-x:hover,.gq-x:focus-visible{border-color:var(--ecco-theme-accent,#ffdc24)!important;color:var(--ecco-theme-accent,#ffdc24)!important}
.gq-row{width:100%;text-align:left;padding:8px 10px;border-radius:9px;border:1px solid transparent;background:transparent;color:var(--ecco-theme-text,#fff);cursor:pointer}
.gq-row:hover:not(:disabled){background:var(--ecco-theme-control,#302a54)}
.gq-row[aria-checked=true]{border-color:var(--ecco-theme-accent,#ffdc24)}
.gq-row:disabled{opacity:.45;cursor:not-allowed}
.gq-row:focus-visible{outline:2px solid var(--ecco-theme-accent,#ffdc24);outline-offset:1px}
.gq-dots{color:var(--ecco-theme-accent,#ffdc24);letter-spacing:1px}
.gq-wait{font-weight:600}
.gq-wait[data-tone=free]{color:var(--ecco-theme-success,#7bcf9b)}
.gq-wait[data-tone=busy]{color:var(--ecco-theme-accent,#ffdc24)}
.gq-wait[data-tone=slow]{color:var(--ecco-theme-warning,#f0a35e)}
.gq-queue{position:relative;background:var(--ecco-theme-control,#3a3778);border-color:var(--ecco-theme-accent,#ffdc24);color:var(--ecco-theme-text,#fff)}
.gq-count{display:inline-block;margin-left:6px;padding:0 7px;border-radius:999px;background:var(--ecco-theme-accent,#ffdc24);color:var(--ecco-theme-background,#17152f);font-weight:700}
.gq-dialog{width:min(1040px,96vw);max-width:96vw}
.gq-progress{display:grid;grid-template-columns:minmax(0,1fr) 44px;gap:8px;align-items:center;margin:8px 0 12px}
.gq-pct{text-align:right;font-weight:600;color:var(--ecco-theme-accent,#ffdc24)}
.gq-ribbon{display:flex;gap:6px;align-items:center;flex-wrap:nowrap}
.gq-tabs{display:flex;gap:5px;flex-wrap:nowrap;overflow-x:auto;min-width:0}
.gq-tab{white-space:nowrap;border-radius:999px;background:transparent;border:1px solid var(--ecco-theme-border,#51496f);color:var(--ecco-theme-muted,#a7a4c8);padding:0 12px}
.gq-tab[aria-selected=true]{border-color:var(--ecco-theme-accent,#ffdc24);color:var(--ecco-theme-accent,#ffdc24)}
.gq-search{margin-left:auto;flex:0 1 180px;min-width:120px}
.gq-search input{width:100%;box-sizing:border-box;border-radius:999px}
.gq-list{list-style:none;margin:8px 0 0;padding:0 4px 0 0;max-height:min(420px,50vh);overflow-y:scroll}
.gq-item{display:grid;grid-template-columns:22px 44px minmax(0,1fr) 170px 90px 84px;gap:6px;align-items:center;padding:2px 6px;border-radius:6px}
.gq-item:nth-child(even){background:var(--ecco-theme-control-subtle,rgba(255,255,255,.03))}
.gq-item.gq-over{box-shadow:inset 0 2px 0 var(--ecco-theme-accent,#ffdc24)}
.gq-item.gq-dragging{opacity:.5}
.gq-grip{cursor:grab;color:var(--ecco-theme-muted,#8b88b3);user-select:none;display:flex;align-items:center;justify-content:center;background:transparent;border:none}
.gq-grip:focus-visible{outline:2px solid var(--ecco-theme-accent,#ffdc24)}
.gq-title,.gq-model{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.gq-acts{display:flex;gap:4px;justify-content:flex-end}
/* Row actions are quiet icons (mock), not filled buttons. */
.gq-acts>button{background:transparent!important;border:1px solid transparent!important;color:var(--ecco-theme-text,#d6d3f0)!important;box-shadow:none!important}
.gq-acts>button:hover,.gq-acts>button:focus-visible{border-color:var(--ecco-theme-accent,#ffdc24)!important;color:var(--ecco-theme-accent,#ffdc24)!important}
.gq-pager{display:flex;gap:10px;align-items:center;justify-content:center;margin-top:8px}
.gq-pager:empty{display:none}
.gq-foot{display:flex;justify-content:flex-end;margin-top:10px}
.gq-foot button{border-color:var(--ecco-theme-accent,#ffdc24);color:var(--ecco-theme-accent,#ffdc24);border-radius:999px}
/* Image tabs on the Generation tab: one per running picture of yours, only when more than one. */
.gq-image-tabs{display:grid;grid-template-columns:repeat(var(--gq-tabs,2),minmax(0,1fr));border-top:3px solid var(--ecco-theme-border,#2c2a55);margin:12px 0}
.gq-image-tab{display:block;text-align:center;padding:8px 6px;border:none;border-right:1px solid var(--ecco-theme-background,#14132b);background:var(--ecco-theme-control,#1b1a3a);color:var(--ecco-theme-muted,#b5b2d6);cursor:pointer}
.gq-image-tab[aria-selected=true]{background:var(--ecco-theme-panel,#201e44);color:var(--ecco-theme-accent,#ffdc24);box-shadow:inset 0 3px 0 var(--ecco-theme-accent,#ffdc24)}
.gq-image-tab .gq-mini{display:grid;grid-template-columns:minmax(0,1fr) 40px;gap:6px;align-items:center;margin-top:6px}
.gq-image-tab .story-gen-track{height:4px}
.gq-image-tab[data-done] .story-gen-track>span{background:var(--ecco-theme-success,#7bcf9b)}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
/* Audio Queue (owner final mocks, 21 Nov 2026): audio recordings cannot be reordered. */
.gq-dialog[data-kind=audio] [data-gq-act=top],.gq-dialog[data-kind=audio] .gq-grip{display:none}

/* Identical structure, spacing and focus treatment across all generation studios. */
#page .grid:has(>.generation-form),#page .audio-workspace:has(>.generation-form){display:grid;grid-template-columns:minmax(290px,360px) minmax(0,1fr);gap:22px;align-items:start}
#page .generation-form{width:auto;min-width:0;padding:14px;display:flex;flex-direction:column;gap:12px;background:var(--panel,#24203e)}
.generation-section{border:1px solid var(--border,#454065);border-radius:8px;padding:10px;display:flex;flex-direction:column;gap:8px;min-width:0;box-shadow:none}
.generation-section.is-focused{border-color:var(--accent,#ffdc24);box-shadow:0 0 0 1px #ffdc2420}
.generation-section-heading{font-size:calc(13px - 2pt);font-weight:600;color:var(--accent,#ffdc24)}
.generation-form label,.generation-dialog label{display:flex;flex-direction:column;gap:5px;font-size:calc(12px - 2pt);min-width:0}
.generation-form button,.generation-dialog button{min-height:28px;padding:4px 8px;font-size:calc(12px - 2pt);line-height:1.3;width:auto}
.generation-form input,.generation-form select,.generation-dialog input,.generation-dialog select{width:100%;min-width:0;box-sizing:border-box;min-height:32px;font-size:calc(12px - 2pt)}
.generation-section [data-model]>label{font-size:0;gap:0}
.generation-action{text-align:left}
.generation-settings{padding:0;border:0;background:transparent;box-shadow:none}
.generation-settings>summary{list-style:none;display:flex;justify-content:space-between;align-items:center;padding:4px 0;cursor:pointer;font-size:calc(12px - 2pt);color:var(--muted,#b8b0cd)}
.generation-settings>summary::-webkit-details-marker{display:none}
.generation-settings>summary::after{content:'⌄';font-size:calc(16px - 2pt)}
.generation-settings[open]>summary::after{transform:rotate(180deg)}
.generation-references>summary{font-size:calc(13px - 2pt);font-weight:600;color:var(--accent,#ffdc24)}
.generation-settings-body{display:flex;flex-direction:column;gap:10px;padding-top:10px}
.generation-settings:not([open])>.generation-settings-body{display:none}
.generation-selected,.generation-reference-tabs{display:flex;flex-wrap:wrap;gap:7px}
.generation-selected:empty{display:none}
