.lh-viewer-body{display:flex;align-items:center;gap:10px}
.lh-viewer-frame{min-width:0;display:flex;justify-content:center;flex:1 1 auto}
.lh-viewer-body img{max-width:min(86vw,calc(92vw - 120px))}
.lh-viewer-step{flex:none;aspect-ratio:1;display:inline-grid;place-items:center;padding:0;border:1px solid var(--ecco-theme-border,#4a4580);border-radius:50%;background:var(--ecco-theme-control,#302a54);color:var(--accent,#ffdc24);cursor:pointer}
.lh-viewer-step svg{fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.lh-viewer-step:disabled{opacity:.35;cursor:default}
.lh-viewer-step:focus-visible{outline:2px solid var(--accent,#ffdc24);outline-offset:2px}
/* Library at scale (10 November 2026): page bar, loading tiles and video poster frames, in every library.
   Sizes come from the master roster (buttons and inputs); these rules only lay out and color. */
.lh-pager{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 12px;padding:8px 10px;border:1px solid var(--ecco-theme-border,#3a3568);border-radius:8px;background:var(--panel,#1d1a3b)}
.lh-pager-bottom{justify-content:center;margin:14px 0 0;border:0;background:transparent}
.lh-pager-status{margin-right:auto;color:var(--ecco-theme-muted,#c9c5ea)}
.lh-page-step{display:inline-flex;align-items:center;gap:4px}
.lh-page-step svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.lh-page-step:disabled{opacity:.4;cursor:default}
.lh-page-num{min-width:32px}
.lh-page-num[aria-current=page]{background:var(--accent,#ffdc24);color:#1a1633;border-color:var(--accent,#ffdc24);font-weight:600}
.lh-pager-gap{padding:0 4px;color:var(--ecco-theme-muted,#c9c5ea)}
.lh-pager-jump{display:inline-flex;align-items:center;gap:6px;margin-left:6px}
.lh-pager-jump input{width:84px}
.lh-thumb,.lh-mini{position:relative}
.lh-thumb img[src=""],.lh-mini img[src=""],.lh-thumb img:not([src]),.lh-mini img:not([src]),[data-thumb][data-media-failed]{visibility:hidden}
.lh-poster{position:absolute;inset:0}
@keyframes lhShimmer{0%{background-position:-180px 0}100%{background-position:180px 0}}
.lh-thumb.media-loading,.lh-mini.media-loading{background:linear-gradient(90deg,var(--panel,#242147) 0,#332d5c 60px,var(--panel,#242147) 120px)!important;background-size:360px 100%!important;animation:lhShimmer 1.2s linear infinite}
.lh-thumb.media-loading>svg,.lh-mini.media-loading>svg{visibility:hidden}
@media(prefers-reduced-motion:reduce){.lh-thumb.media-loading,.lh-mini.media-loading{animation:none}}
@media(max-width:640px){.lh-pager-status{flex-basis:100%}}
/* Page bar buttons: beat the shared compact-button rule the same way the other Library buttons do. */
body:not(.workspace-entry-mode) #page#page .lh .lh-pager button{display:inline-flex!important;align-items:center;justify-content:center;gap:4px;min-height:0!important;padding:6px 10px!important;line-height:1.2!important;font-weight:400!important;border:1px solid var(--ecco-theme-border,#4a4580);border-radius:6px;background:var(--ecco-theme-control,#302a54);color:var(--ecco-theme-text,#f2f0ff)}
body:not(.workspace-entry-mode) #page#page .lh .lh-pager button[aria-current=page]{background:var(--accent,#ffdc24);border-color:var(--accent,#ffdc24);color:#1a1633;font-weight:600!important}
body:not(.workspace-entry-mode) #page#page .lh .lh-pager button:disabled{opacity:.4;cursor:default}
body:not(.workspace-entry-mode) #page#page .lh .lh-pager-bottom button{padding:6px 14px!important}
/* Full-size image view with details (owner-approved mock, 11 November 2026). Layout only. */
.lh-viewer.lh-viewer-full{box-sizing:border-box;width:96vw;max-width:96vw;height:94vh;max-height:94vh;padding:0;display:grid;grid-template-columns:minmax(0,1fr) 340px;grid-template-rows:minmax(0,1fr);overflow:hidden}
.lh-viewer.lh-viewer-full:not([open]){display:none}
.lh-viewer-full .lh-viewer-main{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:20px;min-width:0;min-height:0}
.lh-viewer-full .lh-viewer-body{width:100%;min-height:0;flex:1 1 auto}
.lh-viewer-full .lh-viewer-frame{height:100%;align-items:center}
.lh-viewer-full .lh-viewer-body img{max-width:100%;max-height:calc(94vh - 80px);object-fit:contain}
.lh-viewer-full .lh-viewer-side{display:flex;flex-direction:column;gap:14px;padding:16px;overflow:auto;min-height:0;height:100%;box-sizing:border-box;border-radius:0;border-left:1px solid var(--ecco-theme-border,#4a4580);position:static;width:auto;max-height:none}
.lh-viewer-facts{display:grid;grid-template-columns:1fr 1fr;gap:8px 12px}
.lh-viewer-prompt summary{cursor:pointer}
.lh-viewer-actions{margin-top:auto;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.lh-viewer-confirm{display:flex;flex-wrap:wrap;gap:8px;align-items:center;width:100%}
@media(max-width:800px){.lh-viewer.lh-viewer-full{grid-template-columns:1fr;grid-template-rows:minmax(0,1fr) auto;overflow:auto}.lh-viewer-full .lh-viewer-side{border-left:0;border-top:1px solid var(--ecco-theme-border,#4a4580)}}

/* Model Sounds (owner-approved mock, 21 Nov 2026): one slim row per voice or sound, small play chips. Sizes from the roster. */
.ms-list{border:1px solid var(--ecco-theme-border,#34316a);border-radius:8px;overflow:hidden}
.ms-section{padding:6px 12px;background:var(--ecco-theme-control,#1a1838);color:var(--ecco-theme-muted,#a7a4c8);border-top:1px solid var(--ecco-theme-border,#34316a)}
.ms-section:first-child{border-top:0}
.ms-row{display:grid;grid-template-columns:minmax(140px,220px) minmax(0,1fr);gap:12px;align-items:center;padding:5px 12px;border-top:1px solid var(--ecco-theme-border,#34316a)}
.ms-name{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ms-chips{display:flex;gap:4px;flex-wrap:wrap}
.ms-chip{display:inline-flex;align-items:center;gap:4px;padding:0 8px 0 5px;border:1px solid var(--ecco-theme-border,#34316a);border-radius:999px;background:transparent;color:var(--ecco-theme-text,#e9e7f7);cursor:pointer}
.ms-chip svg{width:9px;height:9px;fill:var(--ecco-theme-accent,#ffdc24)}
.ms-chip:hover,.ms-chip:focus-visible{border-color:var(--ecco-theme-accent,#ffdc24);outline:none}
.ms-chip.on{background:var(--ecco-theme-accent,#ffdc24);color:var(--ecco-theme-background,#1b1a3a);border-color:var(--ecco-theme-accent,#ffdc24)}
.ms-chip.on svg{fill:var(--ecco-theme-background,#1b1a3a)}
.ms-chip.ms-exp{border-style:dashed;border-color:var(--ecco-theme-warning,#f0a35e)}
.ms-chip.ms-listen{border-style:dashed;border-color:var(--ecco-theme-error,#ff6b6b)}
@media(max-width:760px){.ms-row{grid-template-columns:1fr}}
/* Characters › Create voice › From Model Sounds: the same slim rows, each chip with a Use link. */
.ms-pick{margin-top:10px;display:grid;gap:8px}
.ms-pick .ms-list{max-height:320px;overflow-y:auto}
.ms-pair{display:inline-flex;align-items:center;gap:2px;margin-right:6px}
.ms-use{padding:0 4px}
