.lh-more-menu{position:absolute;right:0;top:100%;z-index:30;display:flex;flex-direction:column;min-width:150px;padding:4px;border:1px solid var(--ecco-theme-border,#3a3568);border-radius:8px;background:var(--panel,#1d1a3b);box-shadow:0 8px 24px rgba(0,0,0,.4)}
.lh-more-menu button{text-align:left;padding:6px 10px;border:0;border-radius:5px;background:transparent;color:var(--ecco-theme-text,#f2f0ff);cursor:pointer}
.lh-more-menu button:hover,.lh-more-menu button:focus-visible{background:rgba(255,255,255,.08)}

