#publishing-status{margin-bottom:18px}
.publishing-status-row{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
.publishing-status-row small{flex-basis:100%;color:var(--muted)}
.publishing-spinner{display:inline-block;width:16px;height:16px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:publishing-spin .8s linear infinite;flex:none}
.publishing-toolbar button[aria-busy=true]{display:flex;align-items:center;gap:6px;opacity:1}
@keyframes publishing-spin{to{transform:rotate(360deg)}}
@media(prefers-reduced-motion:reduce){.publishing-spinner{animation-duration:2s}}

/* Owner final mocks (2026-11-21): text boxes fit their text. */
#publish-form textarea{field-sizing:content;min-height:3.2em}
.publishing-toolbar{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:16px}
.publishing-toolbar:has(#workspace-back){justify-content:space-between}

/* Same compact surface and icon spacing as the Connections and Community panels. */
#workspace-settings-controls{display:inline-flex;align-items:center;gap:6px;padding:4px 8px;margin:0;flex:none;border:1px solid var(--ecco-theme-border,rgba(190,180,215,.22));border-radius:10px;background:linear-gradient(180deg,var(--ecco-theme-control,#302a43),var(--ecco-theme-surface,#242031));box-shadow:inset 0 1px 3px rgba(0,0,0,.35),0 1px 0 rgba(255,255,255,.04)}
#workspace-settings-controls>button,#workspace-settings-controls>.workspace-menu>summary{display:grid!important;place-items:center;width:32px!important;min-width:32px!important;height:32px!important;min-height:32px!important;padding:4px!important;margin:0!important;background:transparent!important;border:0!important;box-shadow:none!important;color:var(--ecco-theme-text,#fff)!important;border-radius:6px!important}
#workspace-settings-controls svg{width:16px!important;height:16px!important;pointer-events:none}
#workspace-settings-controls>button:is(:hover,:focus-visible),#workspace-settings-controls>.workspace-menu>summary:is(:hover,:focus-visible),#workspace-settings-controls>.workspace-menu[open]>summary{color:var(--ecco-theme-accent,#ffdc24)!important}
#workspace-settings-controls>button:focus-visible,#workspace-settings-controls>.workspace-menu>summary:focus-visible{outline:2px solid var(--ecco-theme-accent,#ffdc24);outline-offset:2px}
#workspace-settings-controls>.workspace-menu>.workspace-menu-items{right:0;min-width:180px}
#workspace-settings-controls #workspace-theme-drawer{left:auto;right:100%}
body.workspace-entry-mode #workspace-settings-controls{display:none!important}

/* Story Generation (owner-approved mocks, 2026-11-10). Colors come from the theme; every text size and control
   height comes from design-system/size-roster.json. */
.story-gen{display:flex;flex-direction:column;gap:16px;min-width:0}
.story-gen-toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}
.story-gen-state{display:flex;flex-wrap:wrap;gap:10px;align-items:center;min-width:0}
.story-gen-actions{display:flex;flex-wrap:wrap;gap:8px}
.story-gen-chip{padding:4px 12px;border-radius:999px;font-weight:700;background:var(--ecco-theme-control,#302a54);color:var(--ecco-theme-text,#fff);border:1px solid var(--ecco-theme-border,#51496f)}
.story-gen-chip[data-state=running]{color:var(--ecco-theme-accent,#ffdc24);border-color:var(--ecco-theme-accent,#ffdc24)}
.story-gen-chip[data-state=review]{color:var(--ecco-theme-success,#7bcf9b);border-color:var(--ecco-theme-success,#7bcf9b)}
.story-gen-chip[data-state=failed]{color:var(--ecco-theme-error,#ff6b6b);border-color:var(--ecco-theme-error,#ff6b6b)}
.story-gen [data-gen-note][hidden]{display:none}
.story-gen-overall{display:flex;flex-direction:column;gap:14px}
.story-gen-overall-head{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;align-items:flex-end}
.story-gen-overall-head h2{margin:4px 0 0}
.story-gen-overall-figure{display:flex;flex-direction:column;align-items:flex-end;gap:2px}
.story-gen-percent{font-weight:700;color:var(--ecco-theme-accent,#ffdc24);line-height:1}
.story-gen-track{position:relative;height:10px;border-radius:5px;overflow:hidden;background:var(--ecco-theme-background,#17152f);border:1px solid var(--ecco-theme-border,#51496f)}
.story-gen-track>span{display:block;height:100%;background:var(--ecco-theme-accent,#ffdc24);border-radius:inherit;transition:width .6s ease}
.story-gen-track-large{height:16px;border-radius:8px}
.story-gen-indeterminate>span{width:35%!important;animation:story-gen-slide 1.4s ease-in-out infinite}
@keyframes story-gen-slide{0%{transform:translateX(-100%)}100%{transform:translateX(290%)}}
@media (prefers-reduced-motion:reduce){.story-gen-indeterminate>span{animation:none;width:100%!important;opacity:.35}.story-gen-track>span{transition:none}}
.story-gen-unit[data-status=done] .story-gen-track>span,.story-gen-block[data-status=done]>span{background:var(--ecco-theme-success,#7bcf9b)}
.story-gen-unit[data-status=failed] .story-gen-track>span,.story-gen-block[data-status=failed]>span{background:var(--ecco-theme-error,#ff6b6b)}
.story-gen-map-wrap{display:flex;flex-direction:column;gap:6px}
.story-gen-map{display:grid;grid-template-columns:repeat(var(--cells,12),minmax(0,1fr));gap:4px}
.story-gen-block{display:block;height:20px;border-radius:4px;overflow:hidden;background:var(--ecco-theme-background,#17152f);border:1px solid var(--ecco-theme-border,#51496f)}
.story-gen-block[data-status=running]{border-color:var(--ecco-theme-accent,#ffdc24)}
.story-gen-block[data-status=failed]{border-color:var(--ecco-theme-error,#ff6b6b)}
.story-gen-block>span{display:block;height:100%;background:var(--ecco-theme-accent,#ffdc24)}
.story-gen-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin:0}
.story-gen-stats>div{display:flex;flex-direction:column;gap:2px;padding:10px 12px;border-radius:8px;background:var(--ecco-theme-background,#17152f);border:1px solid var(--ecco-theme-border,#51496f)}
.story-gen-stats dd{margin:0}
.story-gen-columns{display:flex;flex-wrap:wrap;gap:16px;align-items:flex-start}
.story-gen-columns>:first-child{flex:999 1 560px;min-width:0}
.story-gen-columns>:last-child{flex:1 1 300px;min-width:0}
.story-gen-workers,.story-gen-log,.story-gen-fixer{display:flex;flex-direction:column;gap:10px;align-self:flex-start}
.story-gen-unit,.story-gen-fix{display:flex;flex-direction:column;gap:6px;padding:12px;border-radius:10px;background:var(--ecco-theme-background,#17152f);border:1px solid var(--ecco-theme-border,#51496f)}
.story-gen-unit[data-status=failed],.story-gen-fix[data-status=failed]{border-color:var(--ecco-theme-error,#ff6b6b)}
.story-gen-unit p,.story-gen-fix p{margin:0}
.story-gen-unit-head{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px}
.story-gen-unit-state{font-weight:700;color:var(--ecco-theme-accent,#ffdc24)}
.story-gen-unit[data-status=done] .story-gen-unit-state,.story-gen-fix[data-status=done] .story-gen-unit-state{color:var(--ecco-theme-success,#7bcf9b)}
.story-gen-unit[data-status=failed] .story-gen-unit-state,.story-gen-fix[data-status=failed] .story-gen-unit-state{color:var(--ecco-theme-error,#ff6b6b)}
.story-gen-unit[data-status=waiting] .story-gen-unit-state{color:var(--ecco-theme-muted,#b1acc9)}
.story-gen-log ol{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;max-height:360px;overflow:auto}
.story-gen-log li{display:grid;grid-template-columns:auto minmax(0,1fr);gap:8px}
.story-gen-player{display:flex;flex-direction:column;gap:12px}
.story-gen-player video,.story-gen-player audio{width:100%;border-radius:10px;background:#000}
.story-gen-player audio{background:transparent}
.story-gen-strip{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:6px}
.story-gen-frame{display:flex;flex-direction:column;gap:4px;align-items:stretch;padding:4px;border-radius:8px;background:var(--ecco-theme-background,#17152f);border:2px solid var(--ecco-theme-border,#51496f);cursor:pointer;min-width:0;overflow:hidden}
.story-gen-frame canvas{display:block;width:100%;flex:1 1 0;min-height:0;object-fit:cover;border-radius:4px;background:var(--ecco-theme-control,#302a54)}
.story-gen-frame span{color:var(--ecco-theme-muted,#b1acc9);text-align:center}
.story-gen-frame[aria-pressed=true]{border-color:var(--ecco-theme-accent,#ffdc24)}
.story-gen-frame[aria-pressed=true] span{color:var(--ecco-theme-accent,#ffdc24)}
.story-gen-chips{display:flex;flex-wrap:wrap;gap:8px;border:0;margin:0;padding:0}
.story-gen-chips label{display:flex;gap:6px;align-items:center;padding:6px 10px;border-radius:999px;border:1px solid var(--ecco-theme-border,#51496f);cursor:pointer}
.story-gen-chips label:has(input:checked){border-color:var(--ecco-theme-accent,#ffdc24);color:var(--ecco-theme-accent,#ffdc24)}
.story-gen-fixer textarea{width:100%;box-sizing:border-box}
.story-gen-fixer label{display:flex;flex-direction:column;gap:4px}
.story-gen-fixer .story-gen-chips label,.story-gen-fixer .story-gen-check{display:inline-flex;flex-direction:row;align-items:center;gap:8px}
.story-gen-chips input,.story-gen-check input{width:auto;height:auto;min-height:0;margin:0;flex:none}
.story-gen-chips legend{padding:0;margin-bottom:6px}
.story-gen-fixer .story-gen-check{flex-direction:row;align-items:center;gap:8px}
.story-gen-fixer [hidden]{display:none!important}
.story-gen-fixes{display:flex;flex-direction:column;gap:8px;border-top:1px solid var(--ecco-theme-border,#51496f);padding-top:12px}
.story-gen-fixes h3{margin:0}
.story-gen-transcript{display:flex;flex-direction:column;gap:12px;max-height:520px;overflow:auto}
.story-gen-passage p{margin:4px 0 0;line-height:1.7}
.story-gen-word{cursor:pointer;border-radius:3px}
.story-gen-word:hover{background:var(--ecco-theme-control,#302a54)}
.story-gen-word-selected{outline:2px solid var(--ecco-theme-accent,#ffdc24)}
.story-gen-word-fixed{background:color-mix(in srgb,var(--ecco-theme-success,#7bcf9b) 25%,transparent)}
.story-gen-pron{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.story-gen-pron li{display:flex;justify-content:space-between;align-items:center;gap:8px}
.story-gen-images{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px}
.story-gen-image{padding:4px;border-radius:10px;background:var(--ecco-theme-background,#17152f);border:2px solid var(--ecco-theme-border,#51496f);height:auto;cursor:pointer}
.story-gen-image[aria-pressed=true]{border-color:var(--ecco-theme-accent,#ffdc24)}
.story-gen-image img{display:block;width:100%;border-radius:6px}
.story-gen-drawer{position:fixed;top:0;right:0;bottom:0;z-index:60;width:min(460px,100vw);overflow:auto;box-sizing:border-box;border-radius:0;border-left:1px solid var(--ecco-theme-border,#51496f);background:var(--ecco-theme-surface,#252039);box-shadow:-12px 0 32px color-mix(in srgb,var(--ecco-theme-shadow,#000) 45%,transparent);display:flex;flex-direction:column;gap:12px}
.story-gen-drawer[hidden]{display:none}
.story-gen-drawer [data-drawer-body]{display:flex;flex-direction:column;gap:12px}
.story-gen-drawer form{width:auto;max-width:none}
@media (max-width:700px){.story-gen-strip{grid-template-columns:repeat(4,minmax(0,1fr))}.story-gen-overall-figure{align-items:flex-start}}

/* Studio panels replaced by this screen (their grid styles would otherwise override [hidden]). */
#page [data-story-gen-hidden]{display:none!important}

/* Image stories (owner-approved mocks, 2026-11-16): progress and Activity on the left half, the Image box on the
   right half, Publish below it. Layout and theme colors only; sizes come from the roster. */
.story-gen-image-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:stretch}
.story-gen-image-layout.story-gen-image-only{grid-template-columns:minmax(0,1fr)}
.story-gen-image-left{display:flex;flex-direction:column;gap:16px;min-width:0}
.story-gen-image-left>.story-gen-log{align-self:stretch;flex:1 1 auto}
.story-gen-image-layout .story-gen-stats{grid-template-columns:repeat(auto-fit,minmax(110px,1fr))}
.story-gen-bars{display:grid;grid-template-columns:max-content minmax(0,1fr) max-content;align-items:center;gap:12px}
.story-gen-bar-label{font-weight:700}
.story-gen-bar-pct{font-weight:700;color:var(--ecco-theme-accent,#ffdc24);text-align:right;font-variant-numeric:tabular-nums}
.story-gen-track[data-status=done]>span{background:var(--ecco-theme-accent,#ffdc24)}
.story-gen-track[data-status=failed]>span{background:var(--ecco-theme-error,#ff6b6b)}
.story-gen-image-box{display:flex;flex-direction:column;gap:12px;min-width:0}
.story-gen-image-head{display:flex;align-items:center;justify-content:space-between;gap:8px}
.story-gen-image-head h3{margin:0}
.story-gen-image-tools{display:flex;gap:8px}
#page .story-gen-image-tools button.pdf-icon-btn:hover,#page .story-gen-image-tools button.pdf-icon-btn:focus-visible{color:var(--ecco-theme-accent,#ffdc24);border-color:var(--ecco-theme-accent,#ffdc24)}
#page .story-gen-image-tools button.pdf-icon-btn:disabled{opacity:.45;cursor:default;color:var(--ecco-theme-muted,#b1acc9);border-color:#45405e}
.story-gen-image-frame{flex:1 1 auto;display:grid;place-items:center;text-align:center;padding:12px;border:1px dashed var(--ecco-theme-border,#51496f);border-radius:10px}
.story-gen-image-frame[data-filled]{border-style:solid;background:var(--ecco-theme-background,#17152f)}
.story-gen-image-frame img{display:block;max-width:100%;border-radius:8px}
.story-gen-image-frame .story-gen-images{width:100%}
.story-gen-image-actions{display:flex;justify-content:flex-end;margin-top:16px}
.story-gen-bar-detail{margin:0}
/* Image rows sit indented under Overall Progress, 1 pt smaller (owner request 2026-11-16). */
.story-gen-bars-units{grid-column:1/-1;display:grid;grid-template-columns:max-content minmax(0,1fr) max-content;align-items:center;gap:10px 12px;padding-left:24px;font-size:calc(1em - 1pt)}
.story-gen-save-item{display:flex;gap:12px;align-items:center}
.story-gen-save-item img{display:block;width:120px;aspect-ratio:16/9;object-fit:cover;border-radius:6px}
.story-gen-save-item div{display:flex;flex-direction:column;gap:2px}
.story-gen-save-labels{display:flex;flex-direction:column;gap:8px;border:0;margin:0;padding:0}
.story-gen-save-labels legend{font-weight:600;margin-bottom:6px}
.story-gen-save-labels .story-gen-check{display:inline-flex;flex-direction:row;align-items:center;gap:8px}
.story-gen-save-labels .story-gen-check input{width:auto;height:auto;min-height:0;margin:0;flex:none}
.story-gen-save-labels select,.story-gen-save-labels input[type=text]{margin-left:24px;width:calc(100% - 24px);box-sizing:border-box}
.story-gen-save-actions{justify-content:flex-end}
.story-gen-save-actions>button{flex:none}
.story-gen-fullscreen{position:fixed;inset:0;width:100vw;height:100vh;max-width:none;max-height:none;margin:0;padding:20px 24px;box-sizing:border-box;border:0;background:var(--ecco-theme-background,#17152f);color:var(--ecco-theme-text,#fff)}
.story-gen-fullscreen[open]{display:flex;flex-direction:column;gap:12px}
.story-gen-fullscreen::backdrop{background:rgba(5,4,15,.85)}
.story-gen-fullscreen-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.story-gen-fullscreen-head .row{display:flex;align-items:center;gap:12px;white-space:nowrap}
.story-gen-fullscreen-stage{flex:1 1 auto;min-height:0;display:grid;place-items:center}
.story-gen-fullscreen-stage img{max-width:100%;max-height:100%;object-fit:contain;border-radius:6px}
.story-gen-fullscreen button.pdf-icon-btn svg{width:60%;height:60%}
#page .story-gen-fullscreen-head button.pdf-icon-btn,.story-gen-fullscreen button.pdf-icon-btn{display:inline-flex;align-items:center;justify-content:center;width:var(--ecco-size-control-medium);height:var(--ecco-size-control-medium);padding:0;background:transparent;color:var(--ecco-theme-muted,#b1acc9);border:1px solid #45405e;border-radius:6px}
#page .story-gen-fullscreen-head button.pdf-icon-btn:hover,#page .story-gen-fullscreen-head button.pdf-icon-btn:focus-visible,.story-gen-fullscreen button.pdf-icon-btn:hover,.story-gen-fullscreen button.pdf-icon-btn:focus-visible{color:var(--ecco-theme-accent,#ffdc24);border-color:var(--ecco-theme-accent,#ffdc24)}
/* Audio stories (owner-approved mocks, 2026-11-16): the Image Generation layout with one row per worker and the Audio box. */
.story-gen-bars-workers .story-gen-bar-label~.story-gen-bar-label{padding-left:16px;font-weight:500}
.story-gen-image-frame.story-gen-audio-frame{display:block;text-align:left;padding:16px}
.story-gen-audio{display:flex;flex-direction:column;gap:12px;min-width:0}
.story-gen-audio-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap}
.story-gen-wave{display:block;width:100%;height:48px}
.story-gen-audio-time{display:flex;justify-content:space-between;font-variant-numeric:tabular-nums}
.story-gen-audio audio{display:none}
.story-gen-audio .story-gen-transcript{border-top:1px solid var(--ecco-theme-border,#51496f);padding-top:12px}
.story-gen-audio .story-gen-passage p{margin:0 0 8px}
.story-gen-audio .story-gen-fixer{margin:0}
.story-gen-save-audio{display:flex;align-items:center;justify-content:center;gap:3px;width:120px;aspect-ratio:16/9;box-sizing:border-box;border-radius:6px;border:1px solid var(--ecco-theme-border,#51496f);background:var(--ecco-theme-background,#17152f)}
.story-gen-save-audio>span{display:block;width:4px;border-radius:2px;background:var(--ecco-theme-accent,#ffdc24)}
@media (max-width:900px){.story-gen-image-layout{grid-template-columns:minmax(0,1fr)}.story-gen-bars{grid-template-columns:minmax(0,1fr) max-content}.story-gen-bars .story-gen-bar-label{grid-column:1/-1}}
.story-gen-audio .story-gen-wave[hidden],.story-gen-audio .story-gen-fixer[hidden]{display:none}
/* Before the first drawing step (owner request 2026-11-21): a spinner and what is happening, so it never looks stuck. */
.story-gen-starting{display:flex;gap:12px;align-items:center;padding:10px 12px;border-radius:8px;border:1px solid var(--ecco-theme-accent,#ffdc24);background:var(--ecco-theme-background,#17152f)}
.story-gen-starting p{margin:2px 0 0}
.story-gen-spinner{flex:none;width:20px;height:20px;border-radius:50%;border:3px solid var(--ecco-theme-border,#51496f);border-top-color:var(--ecco-theme-accent,#ffdc24);animation:story-gen-spin .9s linear infinite}
.story-gen-image-wait{display:flex;flex-direction:column;align-items:center;gap:10px;animation:story-gen-pulse 1.8s ease-in-out infinite}
.story-gen-image-wait .story-gen-spinner{width:36px;height:36px}
@keyframes story-gen-spin{to{transform:rotate(360deg)}}
@keyframes story-gen-pulse{0%,100%{opacity:1}50%{opacity:.55}}
@media (prefers-reduced-motion:reduce){.story-gen-spinner{animation-duration:2.4s}.story-gen-image-wait{animation:none}}
.story-gen-image-actions:has(#workspace-back){justify-content:space-between;align-items:center}

#story-choice-screen .story-choice-actions{overflow:visible;align-items:flex-start;flex-direction:row}
.intent-menu-wrap{position:relative;text-align:left}
.intent-menu,.intent-submenu{position:absolute;z-index:100;background:var(--ecco-theme-surface,var(--panel,#24203e));color:var(--ecco-theme-text,#fff);border:1px solid var(--ecco-theme-border,var(--border,#514b69));border-radius:8px;padding:5px;box-shadow:0 8px 25px #0003;width:190px}
.intent-menu{top:calc(100% + 5px);left:0}.intent-menu-row{position:relative}.intent-submenu{left:100%;top:-5px;width:230px;max-height:320px;overflow-y:auto}
body.story-choice-mode #story-choice-screen .intent-menu button{display:block;text-align:left;width:100%;height:auto;min-height:32px;padding:8px 10px;background:transparent!important;color:var(--ecco-theme-text,#fff)!important;font-size:calc(14px - 2pt)!important;font-weight:400!important;border:0;border-radius:5px;white-space:normal}
body.story-choice-mode #story-choice-screen .intent-menu button:hover,body.story-choice-mode #story-choice-screen .intent-menu button[aria-expanded=true]{background:var(--ecco-theme-control,#39314d)!important}
.intent-menu p{font-size:calc(13px - 2pt);padding:4px}.intent-menu [hidden],.intent-menu[hidden],#story-setup-form [hidden]{display:none!important}
@media(max-width:700px){#story-choice-screen .story-choice-actions{flex-direction:column;align-items:center}.intent-menu{position:relative;top:auto;margin-top:5px}.intent-submenu{position:relative;left:0;top:0;width:100%;box-shadow:none;border:0;border-left:2px solid var(--ecco-theme-border,#514b69);border-radius:0}}
#page.story-journey-fields label[hidden]{display:none!important}

/* Three browser-style tabs; reuse the Studio palette and native controls. */
#story-workspace-header{margin-bottom:16px}
#story-workspace-header [role=tablist]{display:flex;gap:0;border-bottom:1px solid var(--ecco-theme-border,#51496f);overflow-x:auto}
#story-workspace-header [role=tab]{flex:1;min-width:max-content;border-radius:8px 8px 0 0;border:1px solid var(--ecco-theme-border,#51496f);border-bottom:0;background:var(--ecco-theme-control,#29233f);color:var(--ecco-theme-muted,#b1acc9);padding:11px 16px}
#story-workspace-header [role=tab][aria-selected=true]{background:var(--ecco-theme-surface,#201a35);color:var(--ecco-theme-accent,#ffdc24);box-shadow:inset 0 3px var(--ecco-theme-accent,#ffdc24)}
#story-workspace-header [role=tab]:focus-visible{outline:2px solid var(--ecco-theme-accent,#ffdc24);outline-offset:-4px}
.story-simple-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.story-simple-wide{grid-column:1/-1}
