8163a}.gpu-pod-confirm p{margin:0}.gpu-pod-stop-confirm{background:#ff8f87;color:#2a1214}.gpu-pod-console{margin-top:16px;padding:12px 16px;border:1px solid #4b4766;border-radius:12px;background:#18163a}.gpu-pod-console .eyebrow{margin:0}.gpu-pod-console ol{list-style:none;margin:6px 0 0;padding:0;display:flex;flex-direction:column;gap:4px;font-family:ui-monospace,Menlo,monospace;color:#d3cbeb}.gpu-pod-console li[data-error=true]{color:#ffb3ad}.gpu-status{font-weight:600;color:#d3cbeb}.gpu-card[data-status=ready],.gpu-card[data-status=running]{border-color:#36c4aa}.gpu-card[data-status=ready] .gpu-status,.gpu-card[data-status=running] .gpu-status{color:#66e3c9}.gpu-card[data-status=unknown] .gpu-status{color:#e9c97f}@media(max-width:700px){.gpu-grid{grid-template-columns:1fr}.gpu-picker{padding:18px}.gpu-picker .section-head{flex-wrap:wrap;gap:14px}}

