@media(max-width:900px){.pdf-story-dialog{overflow:auto}.pdf-selection-layout{grid-template-columns:minmax(0,1fr);flex:none}.pdf-review-box{height:65vh;min-height:460px}.pdf-selection-footer{margin-top:16px}.pdf-selection-status{align-items:flex-start;flex-wrap:wrap;gap:4px}.pdf-selection-status>[role=status]{margin-left:0}.pdf-tool-panel{position:fixed;left:5vw;bottom:12vh;width:90vw;max-height:65vh}.pdf-ribbon-spacer{display:none}.pdf-selection-ribbon>[data-extract]{margin-left:auto}}


/* Custom story types are edited within the dropdown. */
